[Resource from github at repo://missingbulb/LaughCounter/sha/d0e62e99b3dc9edf40cf1152fd5544bfa9d6311b/contents/.claudinite-checks.json] {
  "packs": [
    "basics",
    {
      "id": "barriers",
      "via": [
        "basics"
      ]
    },
    "grow_with_claudinite",
    "tidy-repo",
    "github-actions",
    "local/on-device-privacy"
  ],
  "accept": [
    {
      "rule": "warning-suppression",
      "path": "laughcounter/cli.py",
      "reason": "deliberate BLE001 broad-excepts: the listen loop and clip scan must never crash on one bad frame, load failure, ID error, or save error — resilience is the design intent"
    },
    {
      "rule": "warning-suppression",
      "path": "laughcounter/dashboard.py",
      "reason": "N802 on do_GET/do_POST is required by Python's http.server BaseHTTPRequestHandler API — the method names are fixed by the framework and cannot be renamed"
    },
    {
      "rule": "warning-suppression",
      "path": "laughcounter/notify.py",
      "reason": "deliberate BLE001 broad-except: a notification failure must never break the listening loop"
    },
    {
      "rule": "warning-suppression",
      "path": "laughcounter/detector/robust.py",
      "reason": "F401 optional-dependency availability probes (laugh_segmenter, torch) — imported to detect presence of the optional detector stack, not for direct use"
    },
    {
      "rule": "warning-suppression",
      "path": "laughcounter/detector/yamnet.py",
      "reason": "F401 optional-dependency availability probe (numpy) — imported to detect presence of the optional yamnet stack"
    },
    {
      "rule": "warning-suppression",
      "path": "laughcounter/speaker.py",
      "reason": "F401 optional-dependency availability probe (torch) — imported to detect presence of the optional speaker-attribution stack"
    }
  ],
  "maintenance": {
    "delivery": "auto-merge"
  },
  "taskScheduler": {
    "dailyHour": 4,
    "weeklyDay": "Sun",
    "monthlyDay": 1
  },
  "claudinite": {
    "updated": "2026-07-26T19:55:19.894Z",
    "ref": "661670521d0d7db483c9117393f84607358058a2"
  }
}

