node -e "
import('./engine/scheduler/run.mjs').then(async ({planRun}) => {
  const baselining = (await import('./packs/basics/tasks/baselining/task.mjs')).default;
  const tasks = [{ pack: 'basics', id: 'baselining', decl: baselining }];
  const schedule = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
  // A manual run at 09:05 today. The hourly scheduler last succeeded at 08:44.
