1	// The scheduler entrypoint's orchestration core (per-project-scheduling DESIGN
2	// §3). The vendored hourly Action runs this: decide due slots from the run
3	// ledger, discover active tasks, collect only the signals the due tasks declare,
4	// run each precondition, and either dispatch agent work as a `ready-for-agent`
5	// issue or (for `agent_model: none`) run the worker inline.
6	//
7	// This module is the DECISION core, kept injectable so it tests with fakes: the
8	// GitHub I/O (the Actions run-ledger read for `lastSuccess`, the signal
9	// collectors, the issue search/create) is supplied by the thin CLI shell around
10	// `planRun`. The "should this run" verdict is always code here — never the
11	// shell's judgment (the same split the fleet planner uses).
12	
13	import { pathToFileURL } from 'node:url';
14	import { dueSlots, mostRecentSlot } from './slots.mjs';
15	import {
16	  planDispatch, dispatchTitle, dispatchBody, DISPATCH_PREFIX, READY_LABEL, NEEDS_HUMAN_LABEL,
17	  SCHEDULER_LABELS, readyLabelForScope, staleDispatchIssues, staleEscalationComment,
18	  rearmDispatchIssues, readyLabelOn, staleClaimedDispatchIssues, staleClaimComment,
19	  AGENT_RUNNING_LABEL,
20	} from './dispatch.mjs';
21	import { isAgentless } from './model-map.mjs';
22	import { localSignalContext } from './signals/local.mjs';
23	import { runPreprocessing, preprocessingFailure, agentRequestPath, clearAgentRequest, agentRequested } from './preprocess.mjs';
24	
25	// The due tasks, each paired with the slot it runs under. Union the discovered
26	// tasks' frequencies, ask slots which are due (run-ledger math), then map due
27	// frequencies back to their tasks. A task whose frequency isn't due drops out.
28	export function computeDueTaskSlots(tasks, schedule, now, lastSuccess, forced = []) {
29	  const frequencies = [...new Set(tasks.map((t) => t.decl.frequency))];
30	  const due = new Map(dueSlots(frequencies, schedule, now, lastSuccess).map((d) => [d.frequency, d]));
31	  const out = [];
32	  for (const task of tasks) {
33	    const slot = due.get(task.decl.frequency);
34	    if (slot) { out.push({ task, slotId: slot.slotId, slotTime: slot.slotTime }); continue; }
35	    // A FORCED task is evaluated under its most-recent slot even though that slot
36	    // has already been run. Without this the override was inert: the due list is
37	    // computed BEFORE any precondition, so a task whose slot has passed never has
38	    // its precondition consulted at all — and a mid-day forced run is the only
39	    // kind that matters. Being in the due list is not permission to run; the
40	    // task's own precondition still decides (#515).
41	    if (forced.includes(task.id)) {
42	      const s = mostRecentSlot(task.decl.frequency, schedule, now);
43	      out.push({ task, slotId: s.id, slotTime: s.time, forced: true });
44	    }
45	  }
46	  return out;
47	}
48	
49	// The verdict a forced task gets INSTEAD of its precondition. The context line
50	// is generic on purpose — it names the mechanism, not the task — and it is there
51	// because a dispatch issue's Context is the agent's binding scope: a forced
52	// dispatch that carried none would read as a scope of nothing, and the agent
53	// should know it arrived by a hand-started run rather than a met condition.
54	const FORCED_VERDICT = Object.freeze({
55	  run: true,
56	  reason: 'forced by FORCE_TASKS on a manual scheduler run — its precondition was not evaluated',
57	  context: Object.freeze(['This run was forced manually (FORCE_TASKS on a workflow_dispatch); the task\'s own precondition was not evaluated, so nothing here asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.']),
58	});
59	
60	// The task ids a manual run forced, out of the opaque override bag. This is the
61	// ONE key the engine reads from that bag, and it is deliberately generic: it
62	// learns "run these task ids", never what any of them do. No task declaration
63	// mentions forcing, and no precondition is consulted for a forced task — an id
64	// matching no discovered task simply forces nothing.
65	export function forcedTaskIds(overrides = {}) {
66	  return String(overrides.FORCE_TASKS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
67	}
68	
69	// The union of signal names the due tasks declare — the scheduler collects only
70	// these, so a non-daily slot never pays for daily tasks' signals (DESIGN §3.3).
71	export function signalsUnion(dueTaskSlots) {
72	  const names = new Set();
73	  for (const { task } of dueTaskSlots) for (const name of task.decl.precondition_signals) names.add(name);
74	  return [...names];
75	}
76	
77	// The signal-collection lookback: the widest due task's period plus 1h slack
78	// (DESIGN §3.3). Stateless fixed lookback — overlap is absorbed by dedupe.
79	const FREQUENCY_MS = {
80	  hourly: 3600e3, 'daily-2h': 86400e3, 'daily-1h': 86400e3, daily: 86400e3,
81	  'daily+1h': 86400e3, weekly: 7 * 86400e3, monthly: 31 * 86400e3,
82	};
83	export function windowStart(dueTaskSlots, now) {
84	  const widest = Math.max(0, ...dueTaskSlots.map(({ task }) => FREQUENCY_MS[task.decl.frequency] ?? 86400e3));
85	  return new Date(new Date(now).getTime() - widest - 3600e3).toISOString();
86	}
87	
88	// Run one task's precondition in isolation (DESIGN §3.4). A throwing
89	// precondition converges to a skip with the error recorded — it never sinks the
90	// rest of the run; the CLI escalates a thrown precondition to a workflow-failure
91	// issue separately.
92	export function runPrecondition(task, signals, packConfig) {
93	  try {
94	    const v = task.decl.precondition(signals, packConfig) ?? {};
95	    return {
96	      run: v.run === true,
97	      reason: v.reason ?? '',
98	      context: Array.isArray(v.context) ? v.context : [],
99	    };
100	  } catch (e) {
101	    return { run: false, reason: `precondition threw: ${e.message}`, context: [], error: e.message };
102	  }
103	}
104	
105	// A human-readable job-summary line per evaluated task — the observability the
106	// old plan.json gave (DESIGN §3.6).
107	export function renderSummary(evaluations) {
108	  return evaluations.map((e) => {
109	    const verb = !e.run ? 'skip' : e.inline ? 'run-inline' : e.dispatch?.action ?? 'run';
110	    const forced = e.forced ? ' (forced)' : '';
111	    return `- ${e.pack}/${e.task} [${e.slotId}]${forced} ${verb} — ${e.reason || e.dispatch?.reason || ''}`.trimEnd();
112	  }).join('\n');
113	}
114	
115	// Orchestrate one scheduler run into a set of decisions — the reusable core the
116	// CLI wraps with real GitHub I/O. Injected seams:
117	//   collectSignals(names) -> signals object (the declared union, collected once)
118	//   packConfigFor(packId) -> that pack's entry config from .claudinite-checks.json
119	//   existingIssuesFor(pack, task) -> the task family's issues [{number,title,state}]
120	// Returns `{ evaluations }`: one record per due task with its precondition
121	// verdict and, when it runs, either an inline marker (agent_model: none) or a
122	// dispatch decision (planDispatch).
